def agrupar_pagamentos_antigos(apps, schema_editor):
    # Peças já marcadas como pagas viram um pagamento por loja e data (sem usuário: não se sabe quem foi).
    ItemOS = apps.get_model('core', 'ItemOS')
    PagamentoLoja = apps.get_model('core', 'PagamentoLoja')
    pagos = ItemOS.objects.filter(pago_loja_em__isnull=False, loja__isnull=False, pagamento__isnull=True)
    grupos = pagos.values('loja_id', 'pago_loja_em').annotate(valor=Sum(F('quantidade') * F('custo_unitario')))
    for g in grupos:
        p = PagamentoLoja.objects.create(loja_id=g['loja_id'], data=g['pago_loja_em'],
                                         valor=round(g['valor'] or 0, 2))
        pagos.filter(loja_id=g['loja_id'], pago_loja_em=g['pago_loja_em']).update(pagamento=p)


